import { ArrowUpToLine, ArrowDownToLine, Trash2, Type } from 'lucide-react'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useUIStore } from '@/store/useUIStore'

interface DomainContextMenuProps {
  domainId: string
  position: { x: number; y: number }
  onClose: () => void
}

export function DomainContextMenu({ domainId, position, onClose }: DomainContextMenuProps) {
  const { domains, updateDomain, removeDomain } = useCanvasStore()
  const { openStylePanel, setSelectedType } = useUIStore()
  const domain = domains.get(domainId)

  if (!domain) return null

  const handleBringToFront = () => {
    const allDomains = Array.from(domains.values())
    const maxZIndex = Math.max(...allDomains.map((d) => d.zIndex || 0), 0)
    updateDomain(domainId, { zIndex: maxZIndex + 1 })
    onClose()
  }

  const handleSendToBack = () => {
    const allDomains = Array.from(domains.values())
    const minZIndex = Math.min(...allDomains.map((d) => d.zIndex || 0), 0)
    updateDomain(domainId, { zIndex: minZIndex - 1 })
    onClose()
  }

  const handleToggleTitle = () => {
    updateDomain(domainId, { titleVisible: !domain.titleVisible })
    onClose()
  }

  const handleOpenStylePanel = () => {
    setSelectedType('domain')
    openStylePanel()
    onClose()
  }

  const handleDelete = () => {
    removeDomain(domainId)
    onClose()
  }

  const menuItems = [
    {
      label: '删除域',
      icon: Trash2,
      action: handleDelete,
      danger: true,
    },
    { divider: true },
    {
      label: '置于顶层',
      icon: ArrowUpToLine,
      action: handleBringToFront,
    },
    {
      label: '置于底层',
      icon: ArrowDownToLine,
      action: handleSendToBack,
    },
    { divider: true },
    {
      label: domain.titleVisible ? '隐藏标题' : '显示标题',
      icon: Type,
      action: handleToggleTitle,
    },
    {
      label: '样式设置...',
      action: handleOpenStylePanel,
    },
  ]

  return (
    <div
      className="fixed bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 py-1 z-50 min-w-[180px]"
      style={{ left: position.x, top: position.y }}
      onClick={(e) => e.stopPropagation()}
    >
      {menuItems.map((item, index) => {
        if (item.divider) {
          return <div key={index} className="h-px bg-gray-200 dark:bg-gray-700 my-1" />
        }

        const Icon = item.icon
        return (
          <button
            key={index}
            onClick={item.action}
            className={`w-full px-4 py-2 text-left flex items-center gap-2 hover:bg-gray-100 dark:hover:bg-gray-700 ${
              item.danger ? 'text-red-600 dark:text-red-400' : 'text-gray-700 dark:text-gray-300'
            }`}
          >
            {Icon && <Icon className="w-4 h-4" />}
            <span className="text-sm">{item.label}</span>
          </button>
        )
      })}
    </div>
  )
}
